import{_ as a,o as e,c as i,a3 as s}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Quick Start | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/guide/quick-start"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/guide/quick-start"}]]},"headers":[],"relativePath":"catter/guide/quick-start.md","filePath":"en/catter/guide/quick-start.md","lastUpdated":1793169279000}'),o={name:"catter/guide/quick-start.md"};function n(r,t,d,l,h,c){return e(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A C++ project with any build system (Make, Ninja, CMake, Meson, etc.)</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Catter is distributed as prebuilt packages on <a href="https://github.com/clice-io/catter/releases" target="_blank" rel="noreferrer">GitHub Releases</a>. Download the archive for your platform, extract it, and add the directory containing the <code>catter</code> executable to your <code>PATH</code>.</p><p>On Linux, extract it to a directory whose path has no space and no colon, and on macOS no colon: the variable that loads catter&#39;s hook into the build (<code>LD_PRELOAD</code>, <code>DYLD_INSERT_LIBRARIES</code>) splits paths there, and catter refuses to run a build from such a directory.</p><p>Prebuilt packages are currently available for:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Architecture</th><th>Package</th></tr></thead><tbody><tr><td>Linux</td><td>x64</td><td><code>catter-&lt;version&gt;.x86_64-unknown-linux-gnu.tar.gz</code></td></tr><tr><td>macOS</td><td>arm64</td><td><code>catter-&lt;version&gt;.aarch64-apple-darwin.tar.gz</code></td></tr><tr><td>Windows</td><td>x64</td><td><code>catter-&lt;version&gt;.x86_64-w64-mingw32.zip</code></td></tr><tr><td>Windows</td><td>arm64</td><td><code>catter-&lt;version&gt;.aarch64-w64-mingw32.zip</code></td></tr></tbody></table><p>Releases on an even minor version (<code>v0.2.0</code>) are stable, and there is none yet. Nightlies are pre-releases on an odd minor, versioned after the UTC hour they were tagged (<code>v0.1.2026102902</code> is 2026-10-29 02:00 UTC): one is published each day <code>main</code> gained builds that passed every test, and nightlies older than 30 days or beyond the newest 25 are deleted, but for the newest one.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Catter is under active development; use the newest nightly. If there is no prebuilt package for your platform, see <a href="./../dev/build">Building from Source</a>.</p></div><h2 id="generate-a-compilation-database" tabindex="-1">Generate a Compilation Database <a class="header-anchor" href="#generate-a-compilation-database" aria-label="Permalink to &quot;Generate a Compilation Database&quot;">​</a></h2><p>Run your build command through catter to capture all compiler invocations:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile-commands</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile_commands.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span></span></code></pre></div><p>This produces a <code>compile_commands.json</code> file in the current directory, ready for use with any language server or static analysis tool.</p><h2 id="command-format" tabindex="-1">Command Format <a class="header-anchor" href="#command-format" aria-label="Permalink to &quot;Command Format&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>catter &lt;command&gt; [options] -- &lt;build-command&gt;</span></span></code></pre></div><p>Breaking down the CDB example:</p><table tabindex="0"><thead><tr><th>Part</th><th>Meaning</th></tr></thead><tbody><tr><td><code>compile-commands</code></td><td>The command: generate a CDB</td></tr><tr><td><code>-o compile_commands.json</code></td><td>An option of the command: the output file path</td></tr><tr><td><code>--</code></td><td>Separator between the command&#39;s arguments and the build command</td></tr><tr><td><code>make</code></td><td>The actual build command to intercept</td></tr></tbody></table><p><code>catter --help</code> lists the commands, and <code>catter &lt;command&gt; --help</code> shows the options of one.</p><h2 id="more-examples" tabindex="-1">More Examples <a class="header-anchor" href="#more-examples" aria-label="Permalink to &quot;More Examples&quot;">​</a></h2><h3 id="command-tree-visualization" tabindex="-1">Command tree visualization <a class="header-anchor" href="#command-tree-visualization" aria-label="Permalink to &quot;Command tree visualization&quot;">​</a></h3><p>View the captured build command DAG as an ASCII tree:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tree</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span></span></code></pre></div><h3 id="using-with-cmake" tabindex="-1">Using with CMake <a class="header-anchor" href="#using-with-cmake" aria-label="Permalink to &quot;Using with CMake&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile-commands</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile_commands.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><h3 id="your-own-handler" tabindex="-1">Your own handler <a class="header-anchor" href="#your-own-handler" aria-label="Permalink to &quot;Your own handler&quot;">​</a></h3><p>Hand the commands to a program of your own, a <a href="./../scripting/handlers">handler</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --handler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;python my_handler.py&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div>',28)])])}const k=a(o,[["render",n]]);export{u as __pageData,k as default};
